// ---------------------------------------------------------------------------
// Sprite-engine testbench: replays sim/vectors.hex (generated by
// sprite_model.py) through Z80 port cycles against the full top level and
// the same board model as tb_top.v, and records every IN result (reads.txt)
// and every dumped frame buffer (frames.txt) for comparison with the
// Python reference model.
// ---------------------------------------------------------------------------
`timescale 1ns/1ps
module tb_sprite;
    localparam real TCLK = 37.037;
    localparam real TZ80 = 563.7;

    reg clk = 0;
    always #(TCLK/2) clk = ~clk;

    wire [10:0] ra;
    wire r_ce_n, r_rw_n, port_oe_n, wait_drv, int_drv;
    wire [7:0] fd;
    wire [5:0] led_n;
    wire r_busy_n_fpga;
    reg  [7:0] z80_addr = 8'h00;
    reg  in_n = 1'b1, out_n = 1'b1;
    wire in_blk = (z80_addr[7:2] == 6'b010100);
    wire #30 iord = in_blk & ~in_n;
    wire #30 iowr = in_blk & ~out_n;
    wire #30 pa0  = z80_addr[0];
    wire #30 pa1  = z80_addr[1];

    // short RENDER_AUTO unit (0.93 ms) so the auto-render test runs quickly
    trs80_card_top #(.AUTO_TICK(25000)) dut (
        .clk27(clk), .btn_s1_n(1'b1),
        .ra(ra), .r_ce_n(r_ce_n), .r_rw_n(r_rw_n), .r_busy_n(r_busy_n_fpga),
        .fd(fd), .iord(iord), .iowr(iowr), .pa({pa1, pa0}),
        .port_oe_n(port_oe_n), .wait_drv(wait_drv), .int_drv(int_drv),
        .sysres_n(1'b1), .led_n(led_n)
    );

    // ---------------- board model (as tb_top.v) ----------------
    reg [7:0] mem [0:2047];
    integer k;
    initial for (k = 0; k < 2048; k = k + 1) mem[k] = 8'h5A;
    assign #15 r_busy_n_fpga = 1'b1;

    wire dp_drives = !r_ce_n && r_rw_n;
    wire [7:0] #70 dp_q = mem[ra];
    wire fpga_drives = dut.fd_oe_pin;
    wire #25      in_n_dir    = in_n;
    wire #(20, 0) port_oe_n_d = port_oe_n;
    wire u3_to_xd = !port_oe_n_d && in_n_dir;
    reg  [7:0] z80_dout = 8'h00;
    wire [7:0] xd_from_fpga, fd_ext;
    wire [7:0] xd = fpga_drives ? xd_from_fpga : dp_drives ? dp_q : u3_to_xd ? z80_dout : 8'hFF;
    genvar b;
    generate for (b = 0; b < 8; b = b + 1) begin : sh
        assign #(100, 15) xd_from_fpga[b] = fd[b];
        assign #(150, 15) fd_ext[b] = xd[b];
    end endgenerate
    assign fd = fpga_drives ? 8'hzz : fd_ext;
    wire [7:0] #25 z80_din = (!port_oe_n && !in_n) ? xd : 8'hFF;
    always @(posedge r_ce_n) if (!r_rw_n) mem[ra] <= xd;

    integer contention = 0;
    realtime clash_t0 = 0;
    wire clash = (fpga_drives + dp_drives + u3_to_xd) > 1;
    always @(clash) if ($realtime > 100.0) begin
        if (clash) clash_t0 = $realtime;
        else if ($realtime - clash_t0 > 10.0) contention = contention + 1;
    end

    // RENDER duration (engine state E_R0 -> back to idle)
    realtime r_t0 = 0, r_max = 0, r_min = 1.0e12;
    integer  renders = 0;
    always @(posedge clk) begin
        if (dut.u_spr.st == 6'd28 && dut.u_spr.busy) r_t0 = $realtime;   // E_R0
        if (dut.u_spr.done && dut.u_spr.cmd == 8'h40) begin
            renders = renders + 1;
            if ($realtime - r_t0 > r_max) r_max = $realtime - r_t0;
            if ($realtime - r_t0 < r_min) r_min = $realtime - r_t0;
        end
    end

    // longest Am9511 BUSY period (per command)
    realtime b_t0 = 0, b_max = 0;
    reg [7:0] b_op = 0, b_maxop = 0;
    always @(posedge dut.u_apu.busy) begin b_t0 = $realtime; b_op = dut.u_apu.op; end
    always @(negedge dut.u_apu.busy)
        if ($realtime - b_t0 > b_max) begin b_max = $realtime - b_t0; b_maxop = b_op; end

    // ---------------- Z80 port cycles ----------------
    task z80_io(input is_in, input [7:0] port, input [7:0] dout, output [7:0] din);
        begin
            z80_addr = port; z80_dout = dout;
            #(TZ80 * 0.6);
            if (is_in) in_n = 1'b0; else out_n = 1'b0;
            #(TZ80 * 1.5);
            while (wait_drv) #(TZ80);
            #(TZ80 * 1.0);
            din = z80_din;
            if (is_in) in_n = 1'b1; else out_n = 1'b1;
            #(TZ80 * 0.9);
        end
    endtask

    // ---------------- vector player ----------------
    // file names can be overridden: +VEC=... +READS=... +FRAMES=...
    reg [31:0] vec [0:16383];
    initial for (k = 0; k < 16384; k = k + 1) vec[k] = 32'h07000000;   // pad with "end"
    integer pc, fr, fd_reads, fd_frames, i, polls, nreads, nframes;
    reg [7:0] d, op, v;
    reg [15:0] a;
    reg [8*64-1:0] f_vec, f_reads, f_frames;
    initial begin
        if (!$value$plusargs("VEC=%s", f_vec))       f_vec    = "vectors.hex";
        if (!$value$plusargs("READS=%s", f_reads))   f_reads  = "reads.txt";
        if (!$value$plusargs("FRAMES=%s", f_frames)) f_frames = "frames.txt";
        $readmemh(f_vec, vec);
        fd_reads  = $fopen(f_reads, "w");
        fd_frames = $fopen(f_frames, "w");
        nreads = 0; nframes = 0;
        #(TCLK * 34000);                       // power-on reset + engine clear
        pc = 0;
        forever begin
            op = vec[pc][31:24]; a = vec[pc][23:8]; v = vec[pc][7:0];
            case (op)
                8'd1: z80_io(0, a[7:0], v, d);
                8'd2: begin
                    z80_io(1, a[7:0], 8'h00, d);
                    $fwrite(fd_reads, "%02x\n", d); nreads = nreads + 1;
                end
                8'd3: begin                    // wait until not BUSY
                    polls = 0;
                    z80_io(1, 8'h53, 8'h00, d);
                    while (d[7] && polls < 20000) begin z80_io(1, 8'h53, 8'h00, d); polls = polls + 1; end
                    if (d[7]) begin $display("TIMEOUT waiting for BUSY to clear at vector %0d", pc); $finish; end
                end
                8'd4: begin
                    for (i = 0; i < 1024; i = i + 1) $fwrite(fd_frames, "%02x\n", mem[i]);
                    nframes = nframes + 1;
                end
                8'd5: mem[a[10:0]] = v;        // Z80-side DPRAM write
                8'd6: begin                    // wait for FRAME to drop and rise again
                    polls = 0;
                    z80_io(1, 8'h53, 8'h00, d);
                    while (d[6] && polls < 20000) begin z80_io(1, 8'h53, 8'h00, d); polls = polls + 1; end
                    while (!d[6] && polls < 40000) begin z80_io(1, 8'h53, 8'h00, d); polls = polls + 1; end
                    if (!d[6]) begin $display("TIMEOUT waiting for auto FRAME"); $finish; end
                end
                8'd8: begin                    // wait until the Am9511 is not BUSY
                    polls = 0;
                    z80_io(1, 8'h51, 8'h00, d);
                    while (d[7] && polls < 1000) begin z80_io(1, 8'h51, 8'h00, d); polls = polls + 1; end
                    if (d[7]) begin $display("TIMEOUT waiting for APU at vector %0d", pc); $finish; end
                end
                8'd7: begin
                    $fclose(fd_reads); $fclose(fd_frames);
                    $display("vectors %0d, reads %0d, frames %0d, bus contention %0d, sim time %0.2f ms",
                             pc, nreads, nframes, contention, $realtime / 1.0e6);
                    if (renders)
                        $display("RENDER: %0d runs, %0.2f - %0.2f ms", renders, r_min / 1.0e6, r_max / 1.0e6);
                    if (b_max > 0)
                        $display("Am9511 longest BUSY: %0.1f us (command %02x)", b_max / 1.0e3, b_maxop);
                    $finish;
                end
                default: begin $display("bad vector %08x at %0d", vec[pc], pc); $finish; end
            endcase
            pc = pc + 1;
        end
    end
endmodule
